insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: M, E, G, J, A, K, Q, D। G के ठीक clockwise कौन बैठा है?','J','Q','M','K','A','Clockwise क्रम में G के तुरंत बाद J है।','8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: M, E, G, J, A, K, Q, D। G के ठीक clockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','53','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में G के ठीक anticlockwise कौन बैठा है?','A','J','M','E','D','G के तुरंत पहले anticlockwise दिशा में E है।','उसी व्यवस्था में G के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','54','pending') ;
