insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में L के बाएँ से स्थान का मान क्या है?','8','2','9','3','A','L का क्रमांक बाएँ से 8 है।','उसी व्यवस्था में L के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','82','pending') ;
