insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: H, Q, B, N, C, G, E, P। N के ठीक clockwise कौन बैठा है?','N','H','C','G','C','Clockwise क्रम में N के तुरंत बाद C है।','8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: H, Q, B, N, C, G, E, P। N के ठीक clockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','133','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में N के ठीक anticlockwise कौन बैठा है?','Q','P','H','B','D','N के तुरंत पहले anticlockwise दिशा में B है।','उसी व्यवस्था में N के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','134','pending') ;
