insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('X के ठीक ऊपर कौन रहता है?','P','X','Y','W','A','क्रम में adjacent मंजिल पर सही व्यक्ति दिया गया है।','X के ठीक ऊपर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','155','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('सबसे ऊपरी मंजिल पर कौन रहता है?','H','W','Y','K','B','नीचे से ऊपर क्रम का अंतिम व्यक्ति W है।','सबसे ऊपरी मंजिल पर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','156','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('7 दिनों में L, C, D, A, N, E, B की अलग-अलग बैठक है। क्रम सोमवार से रविवार: A, B, D, N, L, E, C। B किस दिन है?','सोमवार','मंगलवार','बुधवार','गुरुवार','B','क्रम में B का स्थान 2 है, इसलिए दिन मंगलवार है।','7 दिनों में L, C, D, A, N, E, B की अलग-अलग बैठक है। क्रम सोमवार से रविवार: A, B, D, N, L, E, C। B किस दिन है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','157','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('B और L की बैठक के बीच कितने दिन हैं?','2','3','4','1','A','दिनों का अंतर 3 है; बीच के दिन 2 हैं।','B और L की बैठक के बीच कितने दिन हैं?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','158','pending') ;
