insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में K के ठीक anticlockwise कौन बैठा है?','K','N','G','H','B','K के तुरंत पहले anticlockwise दिशा में N है।','उसी व्यवस्था में K के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','182','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('K के ठीक सामने कौन बैठा है?','G','B','H','L','D','8 सदस्यों के वृत्त में opposite स्थान 4 सीट दूर होता है; वहाँ L है।','K के ठीक सामने कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','183','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('K से clockwise R कितनी सीट दूर है?','5','3','6','4','A','Clockwise अंतर = (4−7) mod 8 = 5।','K से clockwise R कितनी सीट दूर है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','184','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में K, V, U, W, L, Z, G, Q अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: Z, L, U, K, W, Q, V, G। Q कौन-सी मंजिल पर रहता है?','6','3','7','5','A','नीचे से क्रम में Q का स्थान 6 है।','8 मंजिला इमारत में K, V, U, W, L, Z, G, Q अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: Z, L, U, K, W, Q, V, G। Q कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','185','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('U और K के बीच कितनी मंजिलें हैं?','0','1','2','0','A','मंजिलों का अंतर 1 है; बीच की मंजिलें 0 हैं।','U और K के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','186','pending') ;
