insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('10 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: X, Y, F, Z, P, B, A, W, J, E। B और J के बीच कितने व्यक्ति हैं?','2','3','4','1','A','स्थान 6 और 9 हैं, इसलिए बीच में 2 व्यक्ति हैं।','10 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: X, Y, F, Z, P, B, A, W, J, E। B और J के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','209','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में B के बाएँ से स्थान का मान क्या है?','6','5','7','6','A','B का क्रमांक बाएँ से 6 है।','उसी व्यवस्था में B के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','210','pending') ;
