insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('10 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: K, Y, X, M, G, Q, E, N, H, U। Y और N के बीच कितने व्यक्ति हैं?','5','6','7','4','A','स्थान 2 और 8 हैं, इसलिए बीच में 5 व्यक्ति हैं।','10 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: K, Y, X, M, G, Q, E, N, H, U। Y और N के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','241','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में Y के बाएँ से स्थान का मान क्या है?','2','9','3','10','A','Y का क्रमांक बाएँ से 2 है।','उसी व्यवस्था में Y के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','242','pending') ;
