insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('K के ठीक ऊपर कौन रहता है?','H','M','L','F','C','क्रम में adjacent मंजिल पर सही व्यक्ति दिया गया है।','K के ठीक ऊपर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','283','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('सबसे ऊपरी मंजिल पर कौन रहता है?','K','M','V','L','B','नीचे से ऊपर क्रम का अंतिम व्यक्ति M है।','सबसे ऊपरी मंजिल पर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','284','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('7 दिनों में D, K, P, C, H, E, M की अलग-अलग बैठक है। क्रम सोमवार से रविवार: K, P, E, H, M, C, D। H किस दिन है?','सोमवार','मंगलवार','बुधवार','गुरुवार','D','क्रम में H का स्थान 4 है, इसलिए दिन गुरुवार है।','7 दिनों में D, K, P, C, H, E, M की अलग-अलग बैठक है। क्रम सोमवार से रविवार: K, P, E, H, M, C, D। H किस दिन है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','285','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('H और K की बैठक के बीच कितने दिन हैं?','2','3','4','1','A','दिनों का अंतर 3 है; बीच के दिन 2 हैं।','H और K की बैठक के बीच कितने दिन हैं?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','286','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E के अगले दिन किसकी बैठक है?','H','E','D','K','A','क्रम में अगले/पिछले दिन का व्यक्ति यही है।','E के अगले दिन किसकी बैठक है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','287','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E की बैठक किस दिन है?','गुरुवार','मंगलवार','रविवार','बुधवार','D','दिए क्रम के अनुसार E की बैठक बुधवार को है।','E की बैठक किस दिन है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','288','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: Z, L, W, J, Y, U, D, A। U और A के बीच कितने व्यक्ति हैं?','1','2','3','0','A','स्थान 6 और 8 हैं, इसलिए बीच में 1 व्यक्ति हैं।','8 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: Z, L, W, J, Y, U, D, A। U और A के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','289','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में L के बाएँ से स्थान का मान क्या है?','2','7','3','8','A','L का क्रमांक बाएँ से 2 है।','उसी व्यवस्था में L के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','290','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('Y के ठीक बाएँ कौन बैठा है?','A','Z','W','J','D','दिए क्रम में Y के adjacent स्थान पर J है।','Y के ठीक बाएँ कौन बैठा है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','291','pending') ;
