insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('J की बैठक किस दिन है?','बुधवार','शुक्रवार','मंगलवार','शनिवार','A','दिए क्रम के अनुसार J की बैठक बुधवार को है।','J की बैठक किस दिन है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','336','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('11 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: U, H, C, Z, R, G, N, B, K, P, W। W और R के बीच कितने व्यक्ति हैं?','5','6','7','4','A','स्थान 11 और 5 हैं, इसलिए बीच में 5 व्यक्ति हैं।','11 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: U, H, C, Z, R, G, N, B, K, P, W। W और R के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','337','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में N के बाएँ से स्थान का मान क्या है?','7','5','8','6','A','N का क्रमांक बाएँ से 7 है।','उसी व्यवस्था में N के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','338','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('K के ठीक बाएँ कौन बैठा है?','N','U','B','R','C','दिए क्रम में K के adjacent स्थान पर B है।','K के ठीक बाएँ कौन बैठा है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','339','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('Z के दाएँ से दूसरा कौन है?','H','P','G','W','C','दिए गए क्रम में मांगे गए स्थान पर सही व्यक्ति यही है।','Z के दाएँ से दूसरा कौन है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','340','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: K, M, C, J, A, N, G, Q। N के ठीक clockwise कौन बैठा है?','G','K','C','Q','A','Clockwise क्रम में N के तुरंत बाद G है।','8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: K, M, C, J, A, N, G, Q। N के ठीक clockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','341','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में N के ठीक anticlockwise कौन बैठा है?','A','C','M','J','A','N के तुरंत पहले anticlockwise दिशा में A है।','उसी व्यवस्था में N के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','342','pending') ;
