insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में Q, M, G, C, V, N, S, H अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: Q, G, S, M, H, N, V, C। V कौन-सी मंजिल पर रहता है?','7','2','8','6','A','नीचे से क्रम में V का स्थान 7 है।','8 मंजिला इमारत में Q, M, G, C, V, N, S, H अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: Q, G, S, M, H, N, V, C। V कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','345','pending') ;
