insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('F और L के बीच कितनी मंजिलें हैं?','0','1','2','0','A','मंजिलों का अंतर 1 है; बीच की मंजिलें 0 हैं।','F और L के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','362','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('F के ठीक ऊपर कौन रहता है?','R','H','Q','V','A','क्रम में adjacent मंजिल पर सही व्यक्ति दिया गया है।','F के ठीक ऊपर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','363','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('सबसे ऊपरी मंजिल पर कौन रहता है?','Z','V','H','R','D','नीचे से ऊपर क्रम का अंतिम व्यक्ति R है।','सबसे ऊपरी मंजिल पर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','364','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('7 दिनों में M, L, A, J, E, G, D की अलग-अलग बैठक है। क्रम सोमवार से रविवार: G, E, L, J, D, A, M। L किस दिन है?','सोमवार','मंगलवार','बुधवार','गुरुवार','C','क्रम में L का स्थान 3 है, इसलिए दिन बुधवार है।','7 दिनों में M, L, A, J, E, G, D की अलग-अलग बैठक है। क्रम सोमवार से रविवार: G, E, L, J, D, A, M। L किस दिन है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','365','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('A और G की बैठक के बीच कितने दिन हैं?','4','5','6','3','A','दिनों का अंतर 5 है; बीच के दिन 4 हैं।','A और G की बैठक के बीच कितने दिन हैं?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','366','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E के अगले दिन किसकी बैठक है?','M','D','L','E','C','क्रम में अगले/पिछले दिन का व्यक्ति यही है।','E के अगले दिन किसकी बैठक है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','367','pending') ;
