insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('D के ठीक बाएँ कौन बैठा है?','Q','S','Y','C','C','दिए क्रम में D के adjacent स्थान पर Y है।','D के ठीक बाएँ कौन बैठा है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','387','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('S के दाएँ से दूसरा कौन है?','S','J','U','E','B','दिए गए क्रम में मांगे गए स्थान पर सही व्यक्ति यही है।','S के दाएँ से दूसरा कौन है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','388','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: N, Q, K, S, J, C, E, T। E के ठीक clockwise कौन बैठा है?','T','Q','N','E','A','Clockwise क्रम में E के तुरंत बाद T है।','8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: N, Q, K, S, J, C, E, T। E के ठीक clockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','389','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में E के ठीक anticlockwise कौन बैठा है?','C','J','S','K','A','E के तुरंत पहले anticlockwise दिशा में C है।','उसी व्यवस्था में E के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','390','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E के ठीक सामने कौन बैठा है?','Q','E','K','J','C','8 सदस्यों के वृत्त में opposite स्थान 4 सीट दूर होता है; वहाँ K है।','E के ठीक सामने कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','391','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E से clockwise N कितनी सीट दूर है?','2','6','3','1','A','Clockwise अंतर = (0−6) mod 8 = 2।','E से clockwise N कितनी सीट दूर है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','392','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में C, Z, S, D, A, F, Y, Q अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: D, Y, A, S, Q, C, Z, F। C कौन-सी मंजिल पर रहता है?','6','3','7','5','A','नीचे से क्रम में C का स्थान 6 है।','8 मंजिला इमारत में C, Z, S, D, A, F, Y, Q अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: D, Y, A, S, Q, C, Z, F। C कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','393','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('Q और Y के बीच कितनी मंजिलें हैं?','2','3','4','1','A','मंजिलों का अंतर 3 है; बीच की मंजिलें 2 हैं।','Q और Y के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','394','pending') ;
