insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('A के ठीक सामने कौन बैठा है?','A','P','S','H','C','8 सदस्यों के वृत्त में opposite स्थान 4 सीट दूर होता है; वहाँ S है।','A के ठीक सामने कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','439','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('A से clockwise H कितनी सीट दूर है?','3','5','4','2','A','Clockwise अंतर = (2−7) mod 8 = 3।','A से clockwise H कितनी सीट दूर है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','440','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में H, R, J, Y, F, T, V, P अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: V, H, Y, P, R, F, J, T। Y कौन-सी मंजिल पर रहता है?','3','6','4','2','A','नीचे से क्रम में Y का स्थान 3 है।','8 मंजिला इमारत में H, R, J, Y, F, T, V, P अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: V, H, Y, P, R, F, J, T। Y कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','441','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('H और V के बीच कितनी मंजिलें हैं?','0','1','2','0','A','मंजिलों का अंतर 1 है; बीच की मंजिलें 0 हैं।','H और V के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','442','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('H के ठीक ऊपर कौन रहता है?','Y','H','V','F','A','क्रम में adjacent मंजिल पर सही व्यक्ति दिया गया है।','H के ठीक ऊपर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','443','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('सबसे ऊपरी मंजिल पर कौन रहता है?','P','H','Y','T','D','नीचे से ऊपर क्रम का अंतिम व्यक्ति T है।','सबसे ऊपरी मंजिल पर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','444','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E और N की बैठक के बीच कितने दिन हैं?','0','1','2','0','A','दिनों का अंतर 1 है; बीच के दिन 0 हैं।','E और N की बैठक के बीच कितने दिन हैं?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','446','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E के अगले दिन किसकी बैठक है?','D','N','G','L','B','क्रम में अगले/पिछले दिन का व्यक्ति यही है।','E के अगले दिन किसकी बैठक है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','447','pending') ;
