insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('J और A की बैठक के बीच कितने दिन हैं?','1','2','3','0','A','दिनों का अंतर 2 है; बीच के दिन 1 हैं।','J और A की बैठक के बीच कितने दिन हैं?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','494','pending') ;
