insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में S के ठीक anticlockwise कौन बैठा है?','E','H','B','J','B','S के तुरंत पहले anticlockwise दिशा में H है।','उसी व्यवस्था में S के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','518','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('S के ठीक सामने कौन बैठा है?','S','J','E','G','C','8 सदस्यों के वृत्त में opposite स्थान 4 सीट दूर होता है; वहाँ E है।','S के ठीक सामने कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','519','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('S से clockwise J कितनी सीट दूर है?','5','3','6','4','A','Clockwise अंतर = (7−2) mod 8 = 5।','S से clockwise J कितनी सीट दूर है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','520','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में J, X, V, Q, H, G, Z, Y अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: Q, G, X, V, J, Y, H, Z। Z कौन-सी मंजिल पर रहता है?','8','1','1','7','A','नीचे से क्रम में Z का स्थान 8 है।','8 मंजिला इमारत में J, X, V, Q, H, G, Z, Y अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: Q, G, X, V, J, Y, H, Z। Z कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','521','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('X और Y के बीच कितनी मंजिलें हैं?','2','3','4','1','A','मंजिलों का अंतर 3 है; बीच की मंजिलें 2 हैं।','X और Y के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','522','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('J के ठीक ऊपर कौन रहता है?','J','Z','Y','G','C','क्रम में adjacent मंजिल पर सही व्यक्ति दिया गया है।','J के ठीक ऊपर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','523','pending') ;
