insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में M, B, D, C, R, J, W, F अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: W, J, D, C, B, F, M, R। J कौन-सी मंजिल पर रहता है?','2','7','3','1','A','नीचे से क्रम में J का स्थान 2 है।','8 मंजिला इमारत में M, B, D, C, R, J, W, F अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: W, J, D, C, B, F, M, R। J कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','569','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('M और C के बीच कितनी मंजिलें हैं?','2','3','4','1','A','मंजिलों का अंतर 3 है; बीच की मंजिलें 2 हैं।','M और C के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','570','pending') ;
