insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('10 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: R, B, S, L, K, C, W, J, F, G। C और K के बीच कितने व्यक्ति हैं?','0','1','2','0','A','स्थान 6 और 5 हैं, इसलिए बीच में 0 व्यक्ति हैं।','10 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: R, B, S, L, K, C, W, J, F, G। C और K के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','577','pending') ;
