insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: F, V, J, X, A, K, R, N। N और J के बीच कितने व्यक्ति हैं?','4','5','6','3','A','स्थान 8 और 3 हैं, इसलिए बीच में 4 व्यक्ति हैं।','8 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: F, V, J, X, A, K, R, N। N और J के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','657','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में R के बाएँ से स्थान का मान क्या है?','7','2','8','3','A','R का क्रमांक बाएँ से 7 है।','उसी व्यवस्था में R के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','658','pending') ;
