insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('B के ठीक सामने कौन बैठा है?','C','G','Q','D','D','8 सदस्यों के वृत्त में opposite स्थान 4 सीट दूर होता है; वहाँ D है।','B के ठीक सामने कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','679','pending') ;
