insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में A, Y, V, S, R, W, E, D अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: D, V, A, Y, W, S, E, R। V कौन-सी मंजिल पर रहता है?','2','7','3','1','A','नीचे से क्रम में V का स्थान 2 है।','8 मंजिला इमारत में A, Y, V, S, R, W, E, D अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: D, V, A, Y, W, S, E, R। V कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','681','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('D और W के बीच कितनी मंजिलें हैं?','3','4','5','2','A','मंजिलों का अंतर 4 है; बीच की मंजिलें 3 हैं।','D और W के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','682','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E के ठीक ऊपर कौन रहता है?','D','R','S','Y','B','क्रम में adjacent मंजिल पर सही व्यक्ति दिया गया है।','E के ठीक ऊपर कौन रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','683','pending') ;
