insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('10 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: Y, X, C, H, F, P, S, T, B, G। C और X के बीच कितने व्यक्ति हैं?','0','1','2','0','A','स्थान 3 और 2 हैं, इसलिए बीच में 0 व्यक्ति हैं।','10 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: Y, X, C, H, F, P, S, T, B, G। C और X के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','705','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में S के बाएँ से स्थान का मान क्या है?','7','4','8','5','A','S का क्रमांक बाएँ से 7 है।','उसी व्यवस्था में S के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','706','pending') ;
