insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('Q और T के बीच कितनी मंजिलें हैं?','0','1','2','0','A','मंजिलों का अंतर 1 है; बीच की मंजिलें 0 हैं।','Q और T के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','730','pending') ;
