insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('7 दिनों में L, M, P, H, F, A, D की अलग-अलग बैठक है। क्रम सोमवार से रविवार: F, A, L, M, D, P, H। M किस दिन है?','सोमवार','मंगलवार','बुधवार','गुरुवार','D','क्रम में M का स्थान 4 है, इसलिए दिन गुरुवार है।','7 दिनों में L, M, P, H, F, A, D की अलग-अलग बैठक है। क्रम सोमवार से रविवार: F, A, L, M, D, P, H। M किस दिन है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','733','pending') ;
