insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('9 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: Y, W, L, S, Q, V, T, U, M। W और Y के बीच कितने व्यक्ति हैं?','0','1','2','0','A','स्थान 2 और 1 हैं, इसलिए बीच में 0 व्यक्ति हैं।','9 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: Y, W, L, S, Q, V, T, U, M। W और Y के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','785','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में T के बाएँ से स्थान का मान क्या है?','7','3','8','4','A','T का क्रमांक बाएँ से 7 है।','उसी व्यवस्था में T के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','786','pending') ;
