insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में C के ठीक anticlockwise कौन बैठा है?','P','S','J','H','C','C के तुरंत पहले anticlockwise दिशा में J है।','उसी व्यवस्था में C के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','806','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('C के ठीक सामने कौन बैठा है?','J','B','Q','C','B','8 सदस्यों के वृत्त में opposite स्थान 4 सीट दूर होता है; वहाँ B है।','C के ठीक सामने कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','807','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('C से clockwise S कितनी सीट दूर है?','5','3','6','4','A','Clockwise अंतर = (2−5) mod 8 = 5।','C से clockwise S कितनी सीट दूर है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','808','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में L, Q, K, B, X, Y, C, W अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: K, C, B, Y, L, X, W, Q। K कौन-सी मंजिल पर रहता है?','1','8','2','1','A','नीचे से क्रम में K का स्थान 1 है।','8 मंजिला इमारत में L, Q, K, B, X, Y, C, W अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: K, C, B, Y, L, X, W, Q। K कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','809','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('Q और C के बीच कितनी मंजिलें हैं?','5','6','7','4','A','मंजिलों का अंतर 6 है; बीच की मंजिलें 5 हैं।','Q और C के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','810','pending') ;
