insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में B के ठीक anticlockwise कौन बैठा है?','D','J','S','B','B','B के तुरंत पहले anticlockwise दिशा में J है।','उसी व्यवस्था में B के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','886','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('B के ठीक सामने कौन बैठा है?','K','S','J','P','B','8 सदस्यों के वृत्त में opposite स्थान 4 सीट दूर होता है; वहाँ S है।','B के ठीक सामने कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','887','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('B से clockwise C कितनी सीट दूर है?','1','7','2','1','A','Clockwise अंतर = (3−2) mod 8 = 1।','B से clockwise C कितनी सीट दूर है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','888','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में J, V, D, Q, Z, U, B, E अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: Q, E, J, B, U, D, V, Z। E कौन-सी मंजिल पर रहता है?','2','7','3','1','A','नीचे से क्रम में E का स्थान 2 है।','8 मंजिला इमारत में J, V, D, Q, Z, U, B, E अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: Q, E, J, B, U, D, V, Z। E कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','889','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('Z और U के बीच कितनी मंजिलें हैं?','2','3','4','1','A','मंजिलों का अंतर 3 है; बीच की मंजिलें 2 हैं।','Z और U के बीच कितनी मंजिलें हैं?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','890','pending') ;
