insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('N के अगले दिन किसकी बैठक है?','J','E','D','H','B','क्रम में अगले/पिछले दिन का व्यक्ति यही है।','N के अगले दिन किसकी बैठक है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','911','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('E की बैठक किस दिन है?','बुधवार','शुक्रवार','मंगलवार','सोमवार','B','दिए क्रम के अनुसार E की बैठक शुक्रवार को है।','E की बैठक किस दिन है?','','','','','Reasoning','Day Arrangement — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','912','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: V, D, R, X, K, A, C, S। D और K के बीच कितने व्यक्ति हैं?','2','3','4','1','A','स्थान 2 और 5 हैं, इसलिए बीच में 2 व्यक्ति हैं।','8 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: V, D, R, X, K, A, C, S। D और K के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','913','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में R के बाएँ से स्थान का मान क्या है?','3','6','4','7','A','R का क्रमांक बाएँ से 3 है।','उसी व्यवस्था में R के बाएँ से स्थान का मान क्या है?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','914','pending') ;
