insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('11 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: Q, H, A, K, D, C, P, T, E, L, Y। P और H के बीच कितने व्यक्ति हैं?','4','5','6','3','A','स्थान 7 और 2 हैं, इसलिए बीच में 4 व्यक्ति हैं।','11 व्यक्ति एक पंक्ति में बैठे हैं। बाएँ से दाएँ क्रम है: Q, H, A, K, D, C, P, T, E, L, Y। P और H के बीच कितने व्यक्ति हैं?','','','','','Reasoning','Linear Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','945','pending') ;
