insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: T, J, P, R, S, H, E, N। P के ठीक clockwise कौन बैठा है?','N','J','R','H','C','Clockwise क्रम में P के तुरंत बाद R है।','8 व्यक्ति वृत्त में केंद्र की ओर मुख करके बैठे हैं। clockwise क्रम है: T, J, P, R, S, H, E, N। P के ठीक clockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','965','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('उसी व्यवस्था में P के ठीक anticlockwise कौन बैठा है?','N','S','J','T','C','P के तुरंत पहले anticlockwise दिशा में J है।','उसी व्यवस्था में P के ठीक anticlockwise कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','966','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('P के ठीक सामने कौन बैठा है?','S','E','J','P','B','8 सदस्यों के वृत्त में opposite स्थान 4 सीट दूर होता है; वहाँ E है।','P के ठीक सामने कौन बैठा है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','967','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('P से clockwise J कितनी सीट दूर है?','7','1','8','6','A','Clockwise अंतर = (1−2) mod 8 = 7।','P से clockwise J कितनी सीट दूर है?','','','','','Reasoning','Circular Seating — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','968','pending') ;
insert into public.questions (question,option_a,option_b,option_c,option_d,correct_answer,explanation,question_hi,option_a_hi,option_b_hi,option_c_hi,option_d_hi,subject,topic,subtopic,difficulty,language,exam,source,status) values ('8 मंजिला इमारत में E, N, B, W, L, S, G, T अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: T, W, L, G, B, E, S, N। E कौन-सी मंजिल पर रहता है?','6','3','7','5','A','नीचे से क्रम में E का स्थान 6 है।','8 मंजिला इमारत में E, N, B, W, L, S, G, T अलग-अलग मंजिलों पर रहते हैं। नीचे से ऊपर क्रम है: T, W, L, G, B, E, S, N। E कौन-सी मंजिल पर रहता है?','','','','','Reasoning','Floor Puzzle — Hard','','Moderate','Hindi','IBPS RRB Prelims','IBPS_RRB_PRELIMS_PUZZLE_SEATING_HARD_SET_2_1000_HINDI(1).txt','969','pending') ;
